int main(){
 std::ifstream in("convention.in");std::ofstream out("convention.out");int n,m,c;in>>n>>m>>c;
 std::vector<long long> t(n);for(auto& x:t)in>>x;std::sort(t.begin(),t.end());
 auto feasible=[&](long long wait){int buses=0,i=0;while(i<n){int first=i;buses++;while(i<n&&i-first<c&&t[i]-t[first]<=wait)i++;if(buses>m)return false;}return true;};
 long long low=0,high=t.back()-t.front();
 while(low<high){long long mid=low+(high-low)/2;if(feasible(mid))high=mid;else low=mid+1;}
 out<<low<<'\n';
}
