#include <algorithm>
#include <fstream>
#include <functional>
#include <queue>
#include <utility>
#include <vector>
int main(){
 std::ifstream in("convention2.in");std::ofstream out("convention2.out");int n;in>>n;
 std::vector<long long> arrival(n),duration(n);std::vector<std::pair<long long,int>> order;
 for(int i=0;i<n;i++){in>>arrival[i]>>duration[i];order.push_back({arrival[i],i});}
 std::sort(order.begin(),order.end());std::priority_queue<int,std::vector<int>,std::greater<int>> waiting;
 int next=0,served=0;long long clock=0,longest=0;
 while(served<n){
  if(waiting.empty()&&next<n)clock=std::max(clock,order[next].first);
  while(next<n&&order[next].first<=clock){waiting.push(order[next].second);next++;}
  int cow=waiting.top();waiting.pop();longest=std::max(longest,clock-arrival[cow]);clock+=duration[cow];served++;
 }
 out<<longest<<'\n';
}
