int main(){
 std::ifstream in("mooyomooyo.in");std::ofstream out("mooyomooyo.out");int n,k;in>>n>>k;std::vector<std::string> board(n);for(auto& row:board)in>>row;
 while(true){
  std::vector<std::vector<bool>> seen(n,std::vector<bool>(10,false)),remove(n,std::vector<bool>(10,false));bool changed=false;
  for(int r=0;r<n;r++)for(int c=0;c<10;c++)if(board[r][c]!='0'&&!seen[r][c]){
   std::vector<std::pair<int,int>> region,stack={{r,c}};seen[r][c]=true;
   while(!stack.empty()){
    auto [x,y]=stack.back();stack.pop_back();region.push_back({x,y});
    std::pair<int,int> neighbors[4]={{x-1,y},{x+1,y},{x,y-1},{x,y+1}};
    for(auto [a,b]:neighbors)if(a>=0&&a<n&&b>=0&&b<10&&!seen[a][b]&&board[a][b]==board[r][c]){seen[a][b]=true;stack.push_back({a,b});}
   }
   if(static_cast<int>(region.size())>=k){changed=true;for(auto [x,y]:region)remove[x][y]=true;}
  }
  if(!changed)break;
  for(int r=0;r<n;r++)for(int c=0;c<10;c++)if(remove[r][c])board[r][c]='0';
  for(int c=0;c<10;c++){int write=n-1;for(int r=n-1;r>=0;r--)if(board[r][c]!='0')board[write--][c]=board[r][c];while(write>=0)board[write--][c]='0';}
 }
 for(const auto& row:board)out<<row<<'\n';
}
